var t=[{title:`Nejdřív ověřte, že jde o plató`,text:`Jeden zklamávající trénink plató není. Porovnejte několik týdnů za podobných podmínek: stejný cvik, zátěž, rozsah a úsilí. Změny vybavení, spánku nebo techniky mohou způsobit, že čísla vypadají horší, i když kondice neklesá. Zaznamenejte dost podrobností, abyste rozeznali skutečný trend od výkyvů ode dne ke dni.`},{title:`Zkontrolujte základy`,text:`Dokončili jste své tréninky? Zůstával odpor náročný a regenerovali jste mezi tréninky? Byl objem pro vás správný? Někdy je zátěž příliš nízká a někdy vyšší, než je potřeba. Cvik se také může zastavit proto, že jste ten pohyb nepraktikovali pravidelně, zatímco se svaly stále adaptují.`},{title:`Udělejte jednu užitečnou změnu`,text:`Pokud opakování dokončujete snadno, přidejte trochu zátěže nebo použijte dvojitou progresi. Pokud se hromadí únava a výkon klesá, na čas omezte náročné série nebo upravte rozvrh. Pokud se jeden pohyb přestal zlepšovat, zkuste změnu techniky nebo blízce příbuznou variantu a zbytek programu nechte, jak je.`},{title:`Pomalejší zisky v čase`,text:`Začátečníci se často zlepšují rychle, částečně proto, že se pohyby učí. Zkušení cvičenci postupují pomaleji a v menších krocích. Růst svalů se měří dlouho, takže nezměněná váha nebo jediný test výkonu neprokazuje, že váš trénink selhal. Nechte lékaře zkontrolovat únavu, kterou si nedokážete vysvětlit, nebo jiné přetrvávající zdravotní příznaky.`},{title:`Použití v TrainUp`,text:`Historie ukazuje vaše tréninky, průměrné úsilí a graf za 4 týdny, což vám může pomoci odhalit možné plató. TrainUp nikdy nemění váš plán podle méně než 3 tréninků, takže jeden těžký den nespustí nový program. Dělejte malé úpravy a po několika trénincích znovu zkontrolujte.`}];var o=[{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: bezpečnost a základy silového tréninku`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Doporučení ACSM k modelu progrese`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var a={sections:t,sources:o};export{a as default,t as sections,o as sources};